// Combine RSS feeds and extract headlines
const feeds = items.map(item => item.json.data || item.json.body || item.json);
const headlines = [];

for (const feed of feeds) {
  const text = typeof feed === 'string' ? feed : JSON.stringify(feed);
  // Extract titles from RSS XML
  const titleMatches = text.match(/<title><!\[CDATA\[(.+?)\]\]><\/title>/g) || text.match(/<title>(.+?)<\/title>/g) || [];
  for (const match of titleMatches) {
    let title = match.replace(/<title><!\[CDATA\[/, '').replace(/\]\]><\/title>/, '').replace(/<title>/, '').replace(/<\/title>/, '').trim();
    if (title && title.length > 10 && !title.includes('News24') && !title.includes('IOL') && !title.includes('RSS')) {
      headlines.push(title);
    }
  }
}

// Take latest 20 headlines
const latest = headlines.slice(0, 20);
return [{ json: { headlines: latest, headlineText: latest.join('\n') } }];

const response = items[0].json;
let text = '';

if (response.content && response.content.parts) {
  text = String(response.content.parts[0].text || '');
} else if (typeof response === 'string') {
  text = response;
} else if (response.text) {
  text = String(response.text);
} else {
  text = JSON.stringify(response);
}

text = text.trim();

// Try to find JSON array
const start = text.indexOf('[');
const end = text.lastIndexOf(']');
if (start >= 0 && end > start) {
  try {
    const topics = JSON.parse(text.substring(start, end + 1));
    if (Array.isArray(topics)) return [{ json: { topics } }];
  } catch(e) {}
}

// Fallback: parse numbered markdown list
const lines = text.split('\n');
const topics = [];
let title = '';
let desc = '';
for (const line of lines) {
  const m = line.match(/^\d+\.\s+\*\*(.+?)\*\*/);
  if (m) {
    if (title) topics.push({ title, description: desc.trim() });
    title = m[1];
    desc = '';
  } else if (title && line.trim()) {
    desc += line.trim() + ' ';
  }
}
if (title) topics.push({ title, description: desc.trim() });

return [{ json: { topics } }];
